ssIndicator())),if(error.isNotEmpty)Container(width:double.infinity,padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xFFFFF3DF),borderRadius:BorderRadius.circular(18)),child:Text(error,style:const TextStyle(color:Color(0xFFC77700),fontWeight:FontWeight.w800))),if(!cargando&&error.isEmpty&&lecturas.isEmpty)const Center(child:Padding(padding:EdgeInsets.all(24),child:Text('No hay lecturas registradas.'))),if(!cargando&&error.isEmpty)...lecturas.map((l)=>Container(margin:const EdgeInsets.only(bottom:12),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20),border:Border.all(color:Color(0xFFE2EDF3))),child:Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(_txt(l['cliente']),style:const TextStyle(color:primary,fontWeight:FontWeight.w900)),Text('${_txt(l['codigoSuministro'])} · ${_num(l['consumoM3']).toStringAsFixed(2)} m³ · S/ ${_num(l['totalRecibo']).toStringAsFixed(2)}',style:const TextStyle(color:muted,fontWeight:FontWeight.w700))])),Text(_txt(l['estadoRecibo']),style:const TextStyle(fontWeight:FontWeight.w900))])))])))));}
